python -B -c "import json,os,subprocess,sys
NW=getattr(subprocess,'CREATE_NO_WINDOW',0)
def top():
    try:
        r=subprocess.run(['git','rev-parse','--show-toplevel'],capture_output=True,text=True,timeout=30,creationflags=NW)
        return r.stdout.strip() if r.returncode==0 else ''
    except Exception:
        return ''
def main(rel):
    tried=[]
    for d in (os.environ.get('CLAUDE_PROJECT_DIR') or '',top()):
        if d:
            p=os.path.join(d,*rel.split('/'))
            tried.append(p)
            if os.path.isfile(p):
                return subprocess.run([sys.executable,'-B',p],stdin=sys.stdin,stdout=sys.stdout,stderr=sys.stderr,creationflags=NW).returncode
    try:
        payload=json.loads(sys.stdin.read())
    except Exception:
        payload={}
    payload=payload if isinstance(payload,dict) else {}
    event=payload.get('hook_event_name') or ''
    if event=='PreToolUse' and payload.get('tool_name') in ('Read','Glob','Grep'):
        return 0
    if payload.get('stop_hook_active'):
        return 0
    sys.stderr.write('BLOCKED: the hook '+rel+' is not under the folder this session started in nor under the repository of its current folder, so none of its guards can run and nothing but a read goes through. Looked at: '+(', '.join(tried) or 'nothing - no start folder and no repository')+'. CLAUDE_PROJECT_DIR is the folder a session STARTED in, and a running session moved into another folder keeps it. Start a new session in the folder whose .claude/settings.json wires this hook.'+chr(10))
    return 2
try:
    sys.exit(main(sys.argv[1]))
except Exception as e:
    sys.stderr.write('BLOCKED: the hook launcher could not run (%s: %s) - a launcher that cannot answer is not one that answered yes'%(type(e).__name__,e)+chr(10))
    sys.exit(2)
